function addPermissionIfPresent(
  allowList: string[],
  permissions: McpUiResourcePermissions,
  key: keyof McpUiResourcePermissions,
  policyName: string,
): void {
  if (permissions[key]) {
    allowList.push(policyName);
  }
}

export function buildAllowAttribute(
  permissions: McpUiResourcePermissions,
): string {
  const allowList: string[] = [];
  addPermissionIfPresent(allowList, permissions, "camera", "camera");
  addPermissionIfPresent(allowList, permissions, "microphone", "microphone");
  addPermissionIfPresent(allowList, permissions, "geolocation", "geolocation");
  addPermissionIfPresent(allowList, permissions, "clipboardWrite", "clipboard-write");
  addPermissionIfPresent(allowList, permissions, "tools", "tools");
  return allowList.join("; ");
}
